#!/usr/bin/env python3
import datetime, hashlib, json, os, pathlib, subprocess, sys
root=pathlib.Path('/private/tmp/tlmc236-auxiliary')
root.mkdir(exist_ok=True)
name=sys.argv[1]
cmd=sys.argv[2:]
for suffix in ['.json','.log','-source.lean']:
 if (root/(name+suffix)).exists():
  raise SystemExit('Refusing to overwrite execution record: '+name+suffix)
inputs={}
for candidate in ['/private/tmp/tlmc236-proof/Conjecture236.lean','/private/tmp/tlmc236-proof/lakefile.toml','/private/tmp/tlmc236-proof/lake-manifest.json','/private/tmp/tlmc236-proof/lean-toolchain']+cmd:
 path=pathlib.Path(candidate)
 if path.is_file():
  inputs[str(path)]=hashlib.sha256(path.read_bytes()).hexdigest()
start=datetime.datetime.now(datetime.timezone.utc).isoformat()
source=pathlib.Path('/private/tmp/tlmc236-proof/Conjecture236.lean')
if source.exists():
 (root/(name+'-source.lean')).write_bytes(source.read_bytes())
env=os.environ.copy()
env['PATH']='/private/tmp/tlmc310-runtime/lean-4.19.0-darwin_aarch64/bin:'+env.get('PATH','')
status=126
with (root/(name+'.log')).open('wb') as log:
 try:
  p=subprocess.Popen(cmd,cwd='/private/tmp/tlmc236-proof',env=env,stdout=log,stderr=subprocess.STDOUT)
  try:
   status=p.wait()
  except KeyboardInterrupt:
   p.terminate()
   status=p.wait()
   log.write(b'\nRECORDER: execution interrupted by operator.\n')
 except OSError as exc:
  log.write((type(exc).__name__+': '+str(exc)+'\n').encode())
end=datetime.datetime.now(datetime.timezone.utc).isoformat()
output=(root/(name+'.log')).read_bytes()
record={'input_sha256':inputs,'command':cmd,'cwd':'/private/tmp/tlmc236-proof','start_utc':start,'end_utc':end,'exit_status':status,'stdout_file':str(root/(name+'.log')),'stdout_sha256':hashlib.sha256(output).hexdigest()}
(root/(name+'.json')).write_text(json.dumps(record,indent=2)+'\n')
print(json.dumps(record,indent=2))
print(output.decode(errors='replace'))
sys.exit(status if status >= 0 else 128-status)
